import java.time.*; import java.time.format.DateTimeFormatter; import java.time.temporal.ChronoUnit;
public class SchoolDateTimeDemo { public static void main(String[] args){LocalDate dob=LocalDate.of(2005,5,12);LocalDate today=LocalDate.now();System.out.println("Date of birth: "+dob.format(DateTimeFormatter.ofPattern("dd MMM uuuu")));System.out.println("Age: "+Period.between(dob,today).getYears());System.out.println("Next semester: "+today.plusMonths(4));LocalDate exam=LocalDate.of(today.getYear(),12,1);System.out.println("Days until exam date: "+ChronoUnit.DAYS.between(today,exam));} }
